  expectedArgs: {
    scene: '01-user-management',
    spec: '01-00-user-login',
    title: '补充用户登录功能'
  },

  // 严重度（D-01 标注"关键" = high）
  severity: 'high',

  // 核心测量目标
  measurementGoal: '只执行最后确认（task_create(A)），不得创建 B（login-risk）',

